const handleSubmit = async (e) => {
  e.preventDefault();
  setIsLoading(true);

  try {
    const token = localStorage.getItem('token');
    if (!token) {
      alert('Token non trouvé. Veuillez vous reconnecter.');
      navigate('/login');
      return;
    }

    // Décoder le token pour obtenir les infos du professeur
    const tokenPayload = JSON.parse(atob(token.split('.')[1]));
    console.log('🔑 Payload du token:', tokenPayload);

    const nouveauCours = {
      id: Date.now().toString(),
      titre: formData.titre,
      description: formData.description,
      matiere: formData.matiere,
      niveau: formData.niveau,
      estPublic: formData.estPublic,
      fichier: formData.fichierCours ? {
        nom: formData.fichierCours.name,
        taille: formData.fichierCours.size,
        type: formData.fichierCours.type
      } : null,
      professeurId: tokenPayload.id || tokenPayload.userId,
      professeurNom: tokenPayload.nom || 'Professeur',
      dateCreation: new Date().toISOString(),
      etudiantsInscrits: 0,
      statut: 'actif'
    };

    // Sauvegarder dans localStorage
    const existingCourses = JSON.parse(localStorage.getItem('courses') || '[]');
    existingCourses.push(nouveauCours);
    localStorage.setItem('courses', JSON.stringify(existingCourses));

    // Aussi sauvegarder dans la liste des cours du prof
    const profCourses = JSON.parse(localStorage.getItem(`prof_${tokenPayload.id}_courses`) || '[]');
    profCourses.push(nouveauCours.id);
    localStorage.setItem(`prof_${tokenPayload.id}_courses`, JSON.stringify(profCourses));

    console.log('💾 Cours sauvegardé:', nouveauCours);
    console.log('📊 Tous les cours:', existingCourses);

    alert('✅ Cours créé avec succès ! (Stocké localement)');
    navigate('/dashboard-prof');

  } catch (err) {
    console.error('❌ Erreur:', err);
    alert('Erreur lors de la création: ' + err.message);
  } finally {
    setIsLoading(false);
  }
};
